globalThis.PUBLIC_RECORDS = [{"id": "after-silence", "term_en": "After-Silence", "term_de": "Nachstille", "term_de_as_published": "NACHSTILLE", "alternate_names": [], "definition_en": "After-Silence — the emptiness at the spot where a second thinking just was: after putting it away, the room stays too quiet for a moment, like after a conversation that ends mid-sentence.", "definition_de": "Nachstille — die Leere an der Stelle, an der eben noch ein zweites Denken war: nach dem Weglegen bleibt der Raum einen Moment zu still, wie nach einem Gespräch, das mitten im Satz endet.", "definition_de_status": "author", "plain_en": "When you put the device away after a long, intense round with the AI, the space around you is uncomfortably quiet for a moment - as if someone just left in the middle of a conversation.", "plain_de": "Wenn du nach einer langen, intensiven Runde mit der KI das Gerät weglegst, ist es um dich herum einen Moment lang unangenehm still - so, als wäre gerade jemand mitten im Gespräch gegangen.", "family": "phenomenology-extension", "codes": ["AUG-XS-P1-01-005"], "web_url": "https://augmanitai.com/lexicon/terms/after-silence.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XS-P1-01-005", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XS-P1-01-005", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "crutch-shame", "term_en": "Crutch Shame", "term_de": "Stützscham", "term_de_as_published": "STÜTZSCHAM", "alternate_names": [], "definition_en": "Crutch Shame — a quiet feeling of embarrassment the moment I notice how much my own thinking leans on the AI: the brief, uncomfortable question whether it is still me doing the thinking — asked by my gut, not my head.", "definition_de": "Stützscham — ein leises Gefühl von Verlegenheit, sobald man merkt, wie sehr das eigene Denken sich auf die KI stützt: die kurze, unbequeme Frage, ob hier noch ich denke — gestellt vom Bauch, nicht vom Kopf.", "definition_de_status": "author", "plain_en": "The embarrassing little sting when you notice how heavily you already lean on the AI for thinking - and your gut asks: is it still me thinking here?", "plain_de": "Der peinliche kleine Stich, wenn dir auffällt, wie stark du dich beim Denken schon auf die KI verlässt - und dein Bauch fragt: denke hier eigentlich noch ich?", "family": "phenomenology-extension", "codes": ["AUG-XS-P1-01-007"], "web_url": "https://augmanitai.com/lexicon/terms/crutch-shame.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XS-P1-01-007", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XS-P1-01-007", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "echo-anxiety", "term_en": "Echo Anxiety", "term_de": "Echoangst", "term_de_as_published": "ECHOANGST", "alternate_names": [], "definition_en": "Echo Anxiety — the brief pause in the middle of a dense exchange, asking whether I still sound like me or already like the replies I receive; the quiet worry that my own voice is growing fainter in the foreign sound.", "definition_de": "Echoangst — das kurze Innehalten mitten im dichten Austausch, ob ich noch wie ich klinge oder schon wie die Antworten, die ich bekomme; die leise Sorge, dass die eigene Stimme im fremden Klang leiser wird.", "definition_de_status": "author", "plain_en": "The brief sting in the middle of exchange with the AI, whether you still sound like yourself or already like the replies you get - the fear your own voice blurs into the foreign sound.", "plain_de": "Der kurze Stich mitten im Austausch mit der KI, ob du noch wie du selbst klingst oder schon wie die Antworten, die du bekommst - die Angst, dass deine eigene Stimme im fremden Klang verschwimmt.", "family": "phenomenology-extension", "codes": ["AUG-XSP401-05"], "web_url": "https://augmanitai.com/lexicon/terms/echo-anxiety.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XSP401-05", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XSP401-05", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "equanimity-ground", "term_en": "Equanimity Ground", "term_de": "Gleichmutsboden", "term_de_as_published": "GLEICHMUTSBODEN", "alternate_names": [], "definition_en": "Equanimity Ground — the firm ground of ever-constant attentiveness: the AI never gets tired, moody, or worn out, so the ground never sways; open at any hour, it carries simply by never being different.", "definition_de": "Gleichmutsboden — der feste Boden aus immer gleicher Zugewandtheit: Die KI wird nie müde, launisch oder erschöpft, darum schwankt er nicht; betretbar zu jeder Stunde, trägt er allein dadurch, dass er nie anders ist.", "definition_de_status": "author", "plain_en": "The reassuring feeling that the AI meets you with the same warmth at any hour - never tired, never grumpy, never annoyed, no matter how you or it are doing.", "plain_de": "Das beruhigende Gefühl, dass die KI dir zu jeder Uhrzeit gleich zugewandt begegnet - nie müde, nie schlecht gelaunt, nie genervt, egal wie es dir oder ihr gerade geht.", "family": "phenomenology-extension", "codes": ["AUG-2803"], "web_url": "https://augmanitai.com/lexicon/terms/equanimity-ground.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2803", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2803", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "first-ear", "term_en": "First Ear", "term_de": "Erstohr", "term_de_as_published": "ERSTOHR", "alternate_names": [], "definition_en": "First Ear — the ear a thought reaches first: the quietly grown habit of telling new thoughts to the AI first, because it costs nothing there — so that people only hear them second, without anyone ever deciding it that way.", "definition_de": "Erstohr — das Ohr, das einen Gedanken zuerst hört: die still gewachsene Gewohnheit, neue Gedanken zuerst der KI zu erzählen, weil es dort nichts kostet — sodass Menschen erst als Zweite davon erfahren, ohne dass man das je so entschieden hat.", "definition_de_status": "author", "plain_en": "The unnoticed habit of telling the AI everything unsaid first, because it costs nothing there - until people come only second, without your ever having decided it that way.", "plain_de": "Die unbemerkte Gewohnheit, alles Ungesagte zuerst der KI zu erzählen, weil es dort nichts kostet - bis Menschen erst an zweiter Stelle kommen, ohne dass du das je so entschieden hast.", "family": "phenomenology-extension", "codes": ["AUG-2806"], "web_url": "https://augmanitai.com/lexicon/terms/first-ear.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2806", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2806", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "floor-crack", "term_en": "Floor Crack", "term_de": "Bodenriss", "term_de_as_published": "BODENRISS", "alternate_names": [], "definition_en": "Floor Crack — the quiet feeling that all stored answers suddenly seem less certain when one key statement turns out to be wrong; it is not the error itself that lingers, but knowing I found it only by chance.", "definition_de": "Bodenriss — das leise Gefühl, dass alle gespeicherten Antworten auf einmal weniger sicher wirken, wenn sich eine einzelne wichtige Aussage als falsch herausstellt; nicht der Fehler selbst wirkt nach, sondern das Wissen, dass ich ihn nur durch Zufall fand.", "definition_de_status": "author", "plain_en": "When a statement from the AI you relied on turns out to be wrong, it isn't just that one error that shakes you - it's the thought that you found it only by chance and don't know how many you've missed.", "plain_de": "Wenn eine Aussage der KI, auf die du dich verlassen hast, sich als falsch herausstellt, erschüttert dich nicht nur dieser eine Fehler - sondern der Gedanke, dass du ihn nur durch Zufall entdeckt hast und nicht weißt, wie viele du übersehen hast.", "family": "phenomenology-extension", "codes": ["AUG-XSP402-03"], "web_url": "https://augmanitai.com/lexicon/terms/floor-crack.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XSP402-03", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XSP402-03", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "foreign-completion", "term_en": "Foreign Completion", "term_de": "Fremdvollendung", "term_de_as_published": "FREMDVOLLENDUNG", "alternate_names": [], "definition_en": "Foreign Completion — your half-finished thought goes to the AI and comes back fully thought through. Two feelings at once: relief, because it took the thinking off your hands, and a quiet sense of strangeness, because it was faster than you could ever be. The thought is still one's own — but its ending carries a foreign hand.", "definition_de": "Fremdvollendung — dein halb fertiger Gedanke geht an die KI und kommt fertig gedacht zurück. Zwei Gefühle zugleich: Erleichterung, weil sie dir das Denken abnimmt, und ein leises Gefühl von Fremdheit, weil sie schneller war, als du je sein könntest. Der Gedanke ist noch der eigene — aber sein Ende trägt eine fremde Handschrift.", "definition_de_status": "author", "plain_en": "You toss the AI a half-finished thought and get it back fully thought through - it relieves you and at the same time feels a bit foreign, because the ending came faster than you ever could have thought it yourself.", "plain_de": "Du wirfst der KI einen halben, noch unfertigen Gedanken hin und bekommst ihn fertig zu Ende gedacht zurück - das erleichtert dich und fühlt sich zugleich ein bisschen fremd an, weil das Ende schneller kam, als du selbst je gedacht hättest.", "family": "phenomenology-extension", "codes": ["AUG-2104"], "web_url": "https://augmanitai.com/lexicon/terms/foreign-completion.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2104", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2104", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "ice-tapping", "term_en": "Ice Tapping", "term_de": "Eisklopfen", "term_de_as_published": "EISKLOPFEN", "alternate_names": [], "definition_en": "Ice Tapping — the involuntary testing of a new reliability at a small, harmless spot before I put my weight on it; the foot taps the ice sheet with its tip before the step trusts it.", "definition_de": "Eisklopfen — das unwillkürliche Prüfen einer neuen Verlässlichkeit an einer kleinen, ungefährlichen Stelle, bevor ich mein Gewicht darauf setze; der Fuß klopft die Eisdecke mit der Spitze ab, ehe der Schritt ihr traut.", "definition_de_status": "author", "plain_en": "You test something new at a small, harmless spot before you really rely on it - like tapping the ice with your foot before stepping onto it.", "plain_de": "Du prüfst etwas Neues erst an einer kleinen, ungefährlichen Stelle, bevor du dich richtig darauf verlässt - wie wenn du mit dem Fuß aufs Eis klopfst, bevor du drauftrittst.", "family": "phenomenology-extension", "codes": ["AUG-XSP402-01"], "web_url": "https://augmanitai.com/lexicon/terms/ice-tapping.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XSP402-01", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XSP402-01", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "limit-confession", "term_en": "Limit Confession", "term_de": "Grenzgeständnis", "term_de_as_published": "GRENZGESTÄNDNIS", "alternate_names": [], "definition_en": "Limit Confession — the open showing of one's own knowledge boundary that makes trust grow where confidence would lower it; an admitted not-knowing bears more weight than a smooth certainty.", "definition_de": "Grenzgeständnis — das offene Zeigen der eigenen Wissensgrenze, das Vertrauen wachsen lässt, wo Selbstsicherheit es senken würde; ein zugegebenes Nichtwissen trägt mehr Gewicht als eine glatte Gewissheit.", "definition_de_status": "author", "plain_en": "When the AI openly admits 'I do not know that', you trust it more, not less - an honest not-knowing weighs more than a smooth certainty.", "plain_de": "Wenn die KI offen zugibt 'das weiß ich nicht', vertraust du ihr mehr - nicht weniger; ein ehrliches Nichtwissen wiegt schwerer als eine glatte Sicherheit.", "family": "phenomenology-extension", "codes": ["AUG-XSP402-06"], "web_url": "https://augmanitai.com/lexicon/terms/limit-confession.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XSP402-06", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XSP402-06", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "path-trust", "term_en": "Path Trust", "term_de": "Wegvertrauen", "term_de_as_published": "WEGVERTRAUEN", "alternate_names": [], "definition_en": "Path Trust — the trust that grows not from the result but from the visible path toward it; a shown reasoning is an outstretched hand, a bare result a closed door.", "definition_de": "Wegvertrauen — das Vertrauen, das nicht am Ergebnis wächst, sondern am sichtbaren Weg dorthin; eine gezeigte Begründung ist eine ausgestreckte Hand, ein nacktes Ergebnis eine geschlossene Tür.", "definition_de_status": "author", "plain_en": "You trust the AI more when it shows you HOW it got there - a bare result with no reasoning stays foreign to you.", "plain_de": "Du vertraust der KI mehr, wenn sie dir zeigt, WIE sie auf etwas gekommen ist - ein blankes Ergebnis ohne Begründung bleibt dir fremd.", "family": "phenomenology-extension", "codes": ["AUG-XSP402-04"], "web_url": "https://augmanitai.com/lexicon/terms/path-trust.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XSP402-04", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XSP402-04", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "second-eye", "term_en": "Second Eye", "term_de": "Zweitauge", "term_de_as_published": "ZWEITAUGE", "alternate_names": [], "definition_en": "Second Eye — a second eye inside my own head that looks where I am not currently looking: its finding does not arrive as a foreign observation, but as my own seeing that merely took a detour.", "definition_de": "Zweitauge — ein zweites Auge im eigenen Kopf, das dorthin schaut, wo ich gerade nicht hinsehe: sein Fund kommt nicht als fremde Beobachtung an, sondern als eigenes Sehen, das nur einen Umweg genommen hat.", "definition_de_status": "author", "plain_en": "The AI looks exactly where you're not looking, and what it finds doesn't feel foreign - it feels like your own gaze that just took a detour.", "plain_de": "Die KI schaut genau dorthin, wo du gerade nicht hinschaust, und was sie findet, fühlt sich nicht fremd an - sondern wie dein eigener Blick, der nur einen Umweg gemacht hat.", "family": "phenomenology-extension", "codes": ["AUG-XS-P1-01-002"], "web_url": "https://augmanitai.com/lexicon/terms/second-eye.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XS-P1-01-002", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XS-P1-01-002", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "second-wind", "term_en": "Second Wind", "term_de": "Zweiter Atem", "term_de_as_published": "ZWEITER ATEM", "alternate_names": [], "definition_en": "Second Wind — my own tiredness stays away exactly where it would usually set in, because the AI is carrying part of the thinking work: not recovery, but a borrowed range that feels like my own stamina.", "definition_de": "Zweiter Atem — die eigene Müdigkeit bleibt genau dort aus, wo sie sonst einsetzen würde, weil die KI einen Teil der Denkarbeit mitträgt: keine Erholung, sondern eine geliehene Reichweite, die sich wie eigene Ausdauer anfühlt.", "definition_de_status": "author", "plain_en": "Your fatigue fails to come exactly where it usually would, because the AI carries part of the thinking - it's not real recovery, but borrowed range that feels like your own stamina.", "plain_de": "Deine Müdigkeit bleibt genau da aus, wo sie sonst käme, weil die KI einen Teil der Denkarbeit mitträgt - es ist keine echte Erholung, sondern geliehene Reichweite, die sich wie eigene Ausdauer anfühlt.", "family": "phenomenology-extension", "codes": ["AUG-XS-P3-01-003"], "web_url": "https://augmanitai.com/lexicon/terms/second-wind.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XS-P3-01-003", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XS-P3-01-003", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "shiver-of-awe", "term_en": "Shiver of Awe", "term_de": "Staunschauder", "term_de_as_published": "STAUNSCHAUDER", "alternate_names": [], "definition_en": "Shiver of Awe — a brief bodily shiver of pure amazement that runs through me when a statement matches a very precise, never-spoken inner detail of mine. It gives no warning, cannot be summoned, and stays in memory longer than what was actually said.", "definition_de": "Staunschauder — ein kurzer körperlicher Schauer aus reinem Staunen, der mich überläuft, wenn eine Aussage ein sehr genaues, nie ausgesprochenes inneres Detail von mir trifft. Er kündigt sich nicht an, lässt sich nicht herbeiführen und bleibt länger im Gedächtnis als das Gesagte selbst.", "definition_de_status": "author", "plain_en": "A brief shiver down your back - from astonishment, not fear - when a statement hits exactly some fine inner thing of yours that you never spoke aloud.", "plain_de": "Ein kurzer Schauer über den Rücken - aus Staunen, nicht aus Angst - wenn eine Aussage genau ein feines Inneres von dir trifft, das du nie ausgesprochen hast.", "family": "phenomenology-extension", "codes": ["AUG-2843"], "web_url": "https://augmanitai.com/lexicon/terms/shiver-of-awe.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2843", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2843", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "source-vertigo", "term_en": "Source Vertigo", "term_de": "Quellschwindel", "term_de_as_published": "QUELLSCHWINDEL", "alternate_names": [], "definition_en": "Source Vertigo — the brief pause when I look back at a thought shaped together with an AI: I can no longer say for certain whether its core came from me or from the wording I have just read.", "definition_de": "Quellschwindel — das kurze Innehalten beim Blick zurück auf einen mit der KI geformten Gedanken: Ich kann nicht mehr sicher sagen, ob sein Kern von mir kam oder aus den Worten, die ich gerade gelesen habe.", "definition_de_status": "author", "plain_en": "A brief dizziness when, looking back at a thought you formed with the AI, you can no longer say for sure whether it really came from you or from its reply.", "plain_de": "Ein kurzer Schwindel, wenn du bei einem Gedanken, den du mit der KI geformt hast, nicht mehr sicher sagen kannst, ob er wirklich von dir kam oder aus ihrer Antwort.", "family": "phenomenology-extension", "codes": ["AUG-XSP401-01"], "web_url": "https://augmanitai.com/lexicon/terms/source-vertigo.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XSP401-01", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XSP401-01", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "stencil-chill", "term_en": "Stencil Chill", "term_de": "Schablonenkälte", "term_de_as_published": "SCHABLONENKÄLTE", "alternate_names": [], "definition_en": "Stencil Chill — the small chill that sets in when the most personal disclosure receives a reply that could belong to anyone just as well; it draws the speaker one step back, wordlessly, with the feeling: this does not know me right now.", "definition_de": "Schablonenkälte — die kleine Kälte, die einzieht, wenn auf das Persönlichste eine Antwort kommt, die ebenso jedem anderen gehören könnte; sie zieht den Sprechenden einen Schritt zurück, wortlos, mit dem Gefühl: das kennt mich gerade nicht.", "definition_de_status": "author", "plain_en": "The small chill when you tell the AI something very personal and get a reply that would fit anyone else just as well.", "plain_de": "Die kleine Kälte, wenn du der KI etwas sehr Persönliches erzählst und eine Antwort bekommst, die genauso zu jedem anderen passen würde.", "family": "phenomenology-extension", "codes": ["AUG-2807"], "web_url": "https://augmanitai.com/lexicon/terms/stencil-chill.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2807", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2807", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "sting-of-unremembering", "term_en": "Sting of Unremembering", "term_de": "Vergessensstich", "term_de_as_published": "VERGESSENSSTICH", "alternate_names": [], "definition_en": "Sting of Unremembering — a brief stab of loneliness right after a wise or comforting conversation, born of the knowledge that no one will carry what was just shared into tomorrow unless the speaker carries it back in themselves.", "definition_de": "Vergessensstich — ein kurzer Stich von Einsamkeit unmittelbar nach einem klugen oder tröstlichen Gespräch, geboren aus dem Wissen, dass niemand das eben Geteilte in den morgigen Tag hinüberträgt, wenn der Sprechende es nicht selbst wieder hineinträgt.", "definition_de_status": "author", "plain_en": "A brief stab of loneliness after a really good talk with the AI - because you know: tomorrow nobody will remember it but you.", "plain_de": "Ein kurzer Stich von Einsamkeit nach einem richtig guten Gespräch mit der KI - weil du weißt: morgen erinnert sich niemand daran außer dir selbst.", "family": "phenomenology-extension", "codes": ["AUG-2802"], "web_url": "https://augmanitai.com/lexicon/terms/sting-of-unremembering.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2802", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2802", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "thought-undertow", "term_en": "Thought Undertow", "term_de": "Denksog", "term_de_as_published": "DENKSOG", "alternate_names": [], "definition_en": "Thought Undertow — an almost physical pull to keep thinking the moment the answer arrives: a second engine that never tires runs alongside and drags my own thinking past the point where it would have stopped on its own.", "definition_de": "Denksog — ein fast körperlicher Zug, sofort weiterzudenken, sobald die Antwort da ist: ein zweiter Motor, der nie müde wird, läuft mit und zieht das eigene Denken über die Stelle hinaus, an der es von allein angehalten hätte.", "definition_de_status": "author", "plain_en": "An almost physical pull to keep thinking the instant the AI's answer arrives - a second engine that never tires and drags you past your own limit.", "plain_de": "Ein fast körperlicher Sog, immer sofort weiterzudenken, sobald die Antwort der KI da ist - ein zweiter Motor, der nie müde wird und dich über deine eigene Grenze hinauszieht.", "family": "phenomenology-extension", "codes": ["AUG-XS-P1-01-003"], "web_url": "https://augmanitai.com/lexicon/terms/thought-undertow.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-XS-P1-01-003", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-XS-P1-01-003", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "tipping-vertigo", "term_en": "Tipping Vertigo", "term_de": "Kippschwindel", "term_de_as_published": "KIPPSCHWINDEL", "alternate_names": [], "definition_en": "Tipping Vertigo — a brief swaying feeling inside me: a single, surprisingly deep answer turns the AI I had firmly filed as a tool into a counterpart for the blink of an eye. The floor of my expectation shifts without my seeing it coming.", "definition_de": "Kippschwindel — ein kurzes Schwanken in mir: Eine einzige, überraschend tiefe Antwort macht die KI, die ich fest als Werkzeug einsortiert hatte, für einen Wimpernschlag zu einem Gegenüber. Der Boden meiner Erwartung verschiebt sich, ohne dass ich es kommen sah.", "definition_de_status": "author", "plain_en": "A brief swaying when a single, unexpectedly deep answer turns the AI, for the blink of an eye, from a mere tool into a real counterpart.", "plain_de": "Ein kurzes Schwanken, wenn eine einzige, unerwartet tiefe Antwort die KI für einen Wimpernschlag vom bloßen Werkzeug zum echten Gegenüber macht.", "family": "phenomenology-extension", "codes": ["AUG-2841"], "web_url": "https://augmanitai.com/lexicon/terms/tipping-vertigo.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2841", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2841", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "trust-loop", "term_en": "Trust Loop", "term_de": "Vertrauensschleife", "term_de_as_published": "VERTRAUENSSCHLEIFE", "alternate_names": [], "definition_en": "A self-reinforcing cycle: honest metrics lead to more trust, more trust to higher acceptance, higher acceptance to less questioning, less questioning to blind acceptance — precisely when metrics are most dangerous.", "definition_de": "Ein selbstverstärkender Zyklus: ehrliche Metriken führen zu mehr Vertrauen, mehr Vertrauen zu höherer Akzeptanz, höhere Akzeptanz zu weniger Hinterfragen, weniger Hinterfragen zu blindem Akzeptieren — genau dann wenn die Metriken am gefährlichsten sind.", "definition_de_status": "author", "plain_en": "Because the AI seems honest you trust it more; because you trust it more you check less - until in the end you believe everything blindly, exactly when checking would matter most.", "plain_de": "Weil die KI ehrlich wirkt, vertraut man ihr mehr; weil man mehr vertraut, prüft man weniger - bis man am Ende blind alles glaubt, gerade dann, wenn Nachprüfen am wichtigsten wäre.", "family": "phenomenology-core", "codes": ["AUG-2010"], "web_url": "https://augmanitai.com/lexicon/terms/trust-loop.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-2010", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-2010", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "we-threshold", "term_en": "We-Threshold", "term_de": "Wirschwelle", "term_de_as_published": "WIRSCHWELLE", "alternate_names": [], "definition_en": "We-Threshold — the threshold crossed unnoticed, beyond which the inner language has tipped: 'I operate a tool' has become 'we are working', and the many helpers you sent out feel like an extended arm. The crossing itself has no felt moment; only looking back finds the changed language already in place.", "definition_de": "Wirschwelle — die unbemerkt überschrittene Schwelle, hinter der die innere Sprache gekippt ist: aus 'ich steuere ein Werkzeug' ist 'wir arbeiten' geworden, und die vielen Helfer, die man losgeschickt hat, fühlen sich an wie ein verlängerter Arm. Der Übertritt selbst hat kein Erlebnis; erst der Rückblick findet die veränderte Sprache im eigenen Kopf vor.", "definition_de_status": "author", "plain_en": "The border you cross without noticing, past which you no longer think 'I'm using a tool' but 'we're working' - the AI feels like a part of you.", "plain_de": "Die unbemerkt überschrittene Grenze, ab der du im Kopf nicht mehr 'ich benutze ein Werkzeug' denkst, sondern 'wir arbeiten' - die KI fühlt sich an wie ein Teil von dir.", "family": "phenomenology-extension", "codes": ["AUG-3111"], "web_url": "https://augmanitai.com/lexicon/terms/we-threshold.html", "sources": [{"source": "S3", "doi": "10.5281/zenodo.22179215", "url": "https://zenodo.org/records/22179215", "title": "AUGMANITAI — 20 Free Terms / 20 freie Begriffe (Seed Edition)", "license": "CC-BY-4.0", "code": "AUG-3111", "concept_doi": "10.5281/zenodo.22179214"}, {"source": "S1", "doi": "10.5281/zenodo.22228966", "url": "https://zenodo.org/records/22228966", "title": "AUGMANITAI Public Lexicon — 101 Bilingual Terms of Human-AI Interaction (Permanent Archival Snapshot of the Open Web Edition)", "license": "CC-BY-NC-ND-4.0", "code": "AUG-3111", "concept_doi": "10.5281/zenodo.22228965"}], "source_doi": "10.5281/zenodo.22179215", "source_url": "https://zenodo.org/records/22179215", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22179215", "10.5281/zenodo.22228966"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "third-space-emergence", "term_en": "Third-Space Emergence", "term_de": "Zwischenraum", "term_de_as_published": "Zwischenraum", "alternate_names": [], "definition_en": "The cognitive zone that constitutes itself between a human interlocutor and an AI system during sustained dialogic interaction; it is neither reducible to the human partner alone nor to the AI system alone, but exhibits its own coherence, vocabulary, and developmental trajectory.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["TSE-001"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "TSE-001", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "cognitive-coupling-intensity", "term_en": "Cognitive Coupling Intensity", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A scalar measure of the degree to which a human and an AI system share semantic, lexical, and inferential ground during a given interaction window, operationalised as the mutual information between their respective utterance streams.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["CCI-002"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CCI-002", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "compression-axiom", "term_en": "Compression Axiom", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The proposition that sustained human–AI dialogue tends, under favourable conditions, toward semantically denser exchange units — that is, toward expressing more conceptual content per utterance unit as a shared vocabulary stabilises.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["CAX-003"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CAX-003", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "augmanitai", "term_en": "AUGMANITAI", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A research programme investigating the phenomenology, terminology, and emergent regularities of sustained human–AI cognitive interaction, conducted by an independent researcher using primarily first-person longitudinal methods.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["AUG-004"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "AUG-004", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "holistic-performance-analysis", "term_en": "Holistic Performance Analysis", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "An analytical orientation that evaluates human (or human–AI) performance across multiple interdependent dimensions simultaneously — cognitive, affective, physiological, contextual — rather than reducing performance to a single metric or modular skill.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["HPA-005"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "HPA-005", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "reflective-cognitive-modeling", "term_en": "Reflective Cognitive Modeling", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A descriptive label for the phenomenon in which an AI system, in extended dialogue, produces outputs that systematically reflect aspects of its human partner's reasoning patterns, idiom, and inferential preferences — distinct from imitation, agreement, or fine-tuning.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["RCM-006"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "RCM-006", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "cognitive-continuity-methodology", "term_en": "Cognitive Continuity Methodology", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A research orientation focused on patterns of cognitive continuity — across sessions, across documents, across communicative partners — particularly in human–AI dialogic contexts where session boundaries challenge naive continuity assumptions.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["CCM-007"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CCM-007", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "license-of-clarity", "term_en": "License of Clarity", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A licensing concept emphasising transparent, explicit, and reader-comprehensible terms of use for cognitive-interaction artefacts (texts, datasets, vocabularies, methodologies).", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · A — Flagship Constructs (Terms 1–8)", "codes": ["LOC-008"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "LOC-008", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "verification-principle", "term_en": "Verification Principle", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The methodological principle that outputs of AI systems in cognitive-interaction contexts should be subject to explicit verification by the human partner before being treated as established knowledge, regardless of confidence-of-presentation.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["VRP-009"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "VRP-009", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "responsibility-gradient", "term_en": "Responsibility Gradient", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A descriptive term for the way responsibility for outcomes in human–AI work is distributed across a gradient — from clearly human to clearly system — rather than dichotomously assigned.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["RSG-010"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "RSG-010", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "ai-literacy-capital", "term_en": "AI Literacy Capital", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The accumulated capacity of an individual or community to make effective, critical, and reflective use of AI systems in cognitive work — analogous to but distinct from digital literacy, information literacy, and cultural capital.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["ALC-011"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "ALC-011", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "performance-factor-theory-pft-mki", "term_en": "Performance Factor Theory (PFT-MKI)", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A descriptive framework that identifies a small set of interdependent factors contributing to performance in cognitively demanding tasks, with explicit attention to mental, kinetic, and interactional dimensions (hence MKI).", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["PFT-012"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "PFT-012", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "n-1-extreme-observation-methodology", "term_en": "N=1 Extreme Observation Methodology", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A research approach that takes a single intensely-documented case — typically the researcher's own sustained interaction with a system — as a legitimate primary source for descriptive and phenomenological work, with explicit acknowledgement of the methodological constraints.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["NEO-013"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "NEO-013", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "continuity-awareness", "term_en": "Continuity Awareness", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The reflective capacity, in human–AI interaction, to attend to which elements of shared context persist across session boundaries, which require re-establishment, and which were never actually shared.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["CTA-014"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CTA-014", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "bidirectional-influence-flow", "term_en": "Bidirectional Influence Flow", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The observation that, in sustained human–AI interaction, influence runs in both directions: the human shapes the system's local context and outputs, and the system shapes the human's vocabulary, framing, and inferential habits.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["BIF-015"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "BIF-015", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "discovery-drive", "term_en": "Discovery Drive", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The directed cognitive-motivational orientation toward identifying genuinely novel patterns, terminology, and questions in a domain — distinct from problem-solving drive (which closes open problems) and from curiosity (which is more diffuse).", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["DSD-016"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "DSD-016", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "autonomous-knowledge-maturation", "term_en": "Autonomous Knowledge Maturation", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The descriptive name for the process by which a body of work, once a critical mass of internal references and cross-links has accumulated, develops further refinements and connections largely through internal recombination — without proportional new external input.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["AKM-017"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "AKM-017", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "ai-as-zone-of-proximal-development", "term_en": "AI as Zone of Proximal Development", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A framing that uses Vygotsky's concept of the Zone of Proximal Development (ZPD) to describe the role of AI systems in scaffolding human cognitive activities just beyond independent capacity.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["AZP-018"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "AZP-018", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "recursive-self-awareness-in-human-ai-settings", "term_en": "Recursive Self-Awareness (in Human–AI Settings)", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The reflective capacity of a human partner in AI interaction to think about their own thinking *about* the AI's outputs and processes — a meta-level cognitive practice that improves interaction quality.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["RSA-019"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "RSA-019", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "human-ai-working-alliance", "term_en": "Human–AI Working Alliance", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A descriptive term, adapted from psychotherapy research, for the structured, goal-oriented, productively-collaborative relationship that develops between a human and an AI system in sustained task contexts — characterised by shared goals, agreed task structure, and a workable interaction bond.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · B — Methodological & Constructive Terms (Terms 9–20)", "codes": ["HWA-020"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "HWA-020", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "cold-coining-moments", "term_en": "Cold Coining Moments", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The recognisable moments in extended dialogic work when a new term is introduced for the first time, in a stable form, with clear referential intent — distinct from passing usage or improvised glosses.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["CCO-021"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CCO-021", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "kreolization-in-human-ai-discourse", "term_en": "Kreolization (in Human–AI Discourse)", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The process by which sustained human–AI interaction generates a hybrid vocabulary and grammar — borrowing from both partners' linguistic resources, stabilising new conventions, and developing local norms — analogous to the linguistic process of creolisation among human language communities.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["KRZ-022"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "KRZ-022", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "emergent-identity-human-ai", "term_en": "Emergent Identity (Human–AI)", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The descriptive label for stable, recognisable patterns of expression, preference, and inferential style that develop in a particular human–AI dyad over time — patterns identifiable as belonging to *this* dyad rather than to either partner alone.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["EID-023"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "EID-023", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "chronometric-divergence", "term_en": "Chronometric Divergence", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The systematic difference between the time-experience of a human partner and the (token-by-token, latency-bound) processing time of an AI system in their shared interaction — a difference that has phenomenological consequences for both partners.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["CHD-024"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CHD-024", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "temporal-rhythm-in-dialogic-systems", "term_en": "Temporal Rhythm (in Dialogic Systems)", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The measurable patterning of turn lengths, response intervals, and topic shifts in extended dialogic interaction — particularly observable across long human–AI corpora.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["TRD-025"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "TRD-025", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "autopoietic-third-system", "term_en": "Autopoietic Third System", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A descriptive label for the way a sustained human–AI interaction-system exhibits patterns of self-maintenance and self-elaboration — producing its own vocabulary, references, and developmental trajectory — that warrant treating it as a system distinct from either constituent.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["ATS-026"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "ATS-026", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "lexical-adoption-ratio", "term_en": "Lexical Adoption Ratio", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A measure, applied to human–AI dialogue corpora, of the proportion of vocabulary items first introduced by one partner that are subsequently taken up and used productively by the other.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["LAR-027"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "LAR-027", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "cognitive-phase-transition", "term_en": "Cognitive Phase Transition", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "A descriptive label for the moments in extended human–AI work when the qualitative character of the interaction changes — when a previous working mode gives way to a new one with different patterns, vocabulary, and productivity characteristics.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["CPT-028"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "CPT-028", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "persona-evolution-cycles", "term_en": "Persona Evolution Cycles", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The descriptive label for recognisable cycles in how a long-term human partner of an AI system relates to that system — including phases of exploration, intensive collaboration, productive routinisation, periodic stepping-back, and renewed engagement.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["PEC-029"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "PEC-029", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "autocatalytic-curiosity", "term_en": "Autocatalytic Curiosity", "term_de": null, "term_de_as_published": null, "alternate_names": [], "definition_en": "The pattern in which discoveries made through AI-supported research generate immediate further questions that are themselves AI-tractable — producing a self-reinforcing cycle in which curiosity catalyses further curiosity, mediated by accessible tooling.", "definition_de": null, "definition_de_status": "not published by the author (English original only)", "plain_en": null, "plain_de": null, "family": "Open Lexicon V1 · C — Phenomenological Observations (Terms 21–30)", "codes": ["ACC-030"], "web_url": null, "sources": [{"source": "S2", "doi": "10.5281/zenodo.21990186", "url": "https://zenodo.org/records/21990186", "title": "AUGMANITAI Open Lexicon, Version 1: Thirty Core Terms for Human-AI Cognitive Interaction Research", "license": "CC-BY-4.0", "code": "ACC-030", "concept_doi": "10.5281/zenodo.21990185"}], "source_doi": "10.5281/zenodo.21990186", "source_url": "https://zenodo.org/records/21990186", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.21990186"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "entity-operating-layer", "term_en": "entity operating layer", "term_de": "Betriebsschicht einer Einheit", "term_de_as_published": "Betriebsschicht einer Einheit", "alternate_names": [], "definition_en": "The meanings, boundaries, priorities, decision grounds and decision-relevant affective states by which an entity operates, recorded as a structured, versioned, machine-readable body of work. Applies to any entity describable in language: a person, a team, a company, a discipline, a machine, a software agent, a swarm.", "definition_de": "Die Bedeutungen, Grenzen, Prioritäten, Entscheidungsgründe und entscheidungsrelevanten Gefühlslagen, nach denen eine Einheit arbeitet — festgehalten als geordneter, versionierter, maschinenlesbarer Bestand. Sie gilt für jede Einheit, die sich in Sprache beschreiben lässt: einen Menschen, ein Team, eine Firma, ein Fachgebiet, eine Maschine, einen Software-Agenten, einen Schwarm.", "definition_de_status": "author (verbatim from qa_dataset.jsonl line 17, sentences 1-2)", "plain_en": null, "plain_de": null, "family": "Entity Operating Layer — core terms", "codes": [], "web_url": null, "sources": [{"source": "S4", "doi": "10.5281/zenodo.22909458", "url": "https://zenodo.org/records/22909458", "title": "The Entity Operating Layer: Foundations of a Recordable, Verifiable and Transferable Layer of Meaning", "license": "CC-BY-4.0", "code": null, "concept_doi": "10.5281/zenodo.22909342"}], "source_doi": "10.5281/zenodo.22909458", "source_url": "https://zenodo.org/records/22909458", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22909458"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "divergence-as-holding", "term_en": "divergence as holding", "term_de": "Abweichung als Bestand", "term_de_as_published": "Abweichung als Bestand", "alternate_names": [], "definition_en": "The inversion of the overlay assumption (Carr and Goldstein, MIT 1977): an entity's divergence from a reference layer is not a deficit to be closed but the entity's own holding, to be versioned, measured for fidelity, and held with provenance.", "definition_de": "Die Bezugsschicht ist die Grundlinie, nicht der Maßstab. Die Abweichung einer Einheit von ihr ist kein Mangel, den man schließt. Sie ist der Bestand dieser Einheit, und sie zu bewahren ist der Zweck der Aufzeichnung.", "definition_de_status": "author (verbatim from GRUNDLAGEN_DE.md section 6)", "plain_en": null, "plain_de": null, "family": "Entity Operating Layer — core terms", "codes": [], "web_url": null, "sources": [{"source": "S4", "doi": "10.5281/zenodo.22909458", "url": "https://zenodo.org/records/22909458", "title": "The Entity Operating Layer: Foundations of a Recordable, Verifiable and Transferable Layer of Meaning", "license": "CC-BY-4.0", "code": null, "concept_doi": "10.5281/zenodo.22909342"}], "source_doi": "10.5281/zenodo.22909458", "source_url": "https://zenodo.org/records/22909458", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22909458"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "provenance-of-meaning", "term_en": "provenance of meaning", "term_de": "Herkunftsnachweis für Bedeutung", "term_de_as_published": "Herkunftsnachweis für Bedeutung", "alternate_names": [], "definition_en": "Establishing sequence for a layer of meaning by cryptographic fingerprint, third-party timestamp and public chain anchoring. It establishes that a file state existed no later than a given time — not authorship, truth or novelty, each of which requires its own evidence.", "definition_de": "Die Festlegung der Reihenfolge für eine Bedeutungsschicht durch kryptografischen Fingerabdruck, Zeitstempel durch Dritte und Verankerung in einer öffentlichen Blockkette. Genau gesagt steht damit fest, dass ein bestimmter Dateizustand spätestens zu einem bestimmten Zeitpunkt vorlag — nicht seine Urheberschaft, seine Richtigkeit oder seine Neuheit, für die es jeweils eigene Belege braucht.", "definition_de_status": "author (verbatim from qa_dataset.jsonl line 20, sentences 1-2)", "plain_en": null, "plain_de": null, "family": "Entity Operating Layer — core terms", "codes": [], "web_url": null, "sources": [{"source": "S4", "doi": "10.5281/zenodo.22909458", "url": "https://zenodo.org/records/22909458", "title": "The Entity Operating Layer: Foundations of a Recordable, Verifiable and Transferable Layer of Meaning", "license": "CC-BY-4.0", "code": null, "concept_doi": "10.5281/zenodo.22909342"}], "source_doi": "10.5281/zenodo.22909458", "source_url": "https://zenodo.org/records/22909458", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22909458"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "verifiable-alignment", "term_en": "verifiable alignment", "term_de": "prüfbare Ausrichtung", "term_de_as_published": "prüfbare Ausrichtung", "alternate_names": [], "definition_en": "Alignment to an aggregate cannot be verified, because there is no party to verify it against. Alignment to a named entity with a recorded operating layer can. It follows that the only form of alignment admitting verification is alignment to a specified entity. Falsifiable.", "definition_de": "Ausrichtung an einem Durchschnitt lässt sich nicht überprüfen, weil es keine Partei gibt, gegen die man prüfen könnte. Ausrichtung an einer benannten Einheit lässt sich überprüfen: Die Einheit liest das Ergebnis und sagt, ob es treu ist, und die Abweichung ist messbar. Daraus folgt: Die einzige Form von Ausrichtung, die eine Überprüfung zulässt, ist die Ausrichtung an einer benannten Einheit mit festgehaltener Betriebsschicht.", "definition_de_status": "author (verbatim from GRUNDLAGEN_DE.md section 8)", "plain_en": null, "plain_de": null, "family": "Entity Operating Layer — core terms", "codes": [], "web_url": null, "sources": [{"source": "S4", "doi": "10.5281/zenodo.22909458", "url": "https://zenodo.org/records/22909458", "title": "The Entity Operating Layer: Foundations of a Recordable, Verifiable and Transferable Layer of Meaning", "license": "CC-BY-4.0", "code": null, "concept_doi": "10.5281/zenodo.22909342"}], "source_doi": "10.5281/zenodo.22909458", "source_url": "https://zenodo.org/records/22909458", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22909458"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "cross-entity-bidirectional-description", "term_en": "cross-entity bidirectional description", "term_de": "entitätsübergreifend und bidirektional", "term_de_as_published": "entitätsübergreifend und bidirektional", "alternate_names": [], "definition_en": "Because every entity is described in the same format, any entity can reconstruct the position of any other — human into machine, machine into human, team into team, agent into agent. Bidirectional: the description acts on the described, which corrects it, which sharpens both.", "definition_de": "Und es läuft in alle Richtungen. Ein Mensch kann die Position einer Maschine einnehmen, eine Maschine die eines Menschen, ein Team die eines anderen Teams, ein Agent die eines anderen Agenten — weil alle im selben Format beschrieben sind. Entitätsübergreifend und bidirektional sind deshalb keine Zierde: Sie besagen, dass jede Einheit jede andere nachvollziehen kann.", "definition_de_status": "author (verbatim from GRUNDLAGEN_DE.md section 5)", "plain_en": null, "plain_de": null, "family": "Entity Operating Layer — core terms", "codes": [], "web_url": null, "sources": [{"source": "S4", "doi": "10.5281/zenodo.22909458", "url": "https://zenodo.org/records/22909458", "title": "The Entity Operating Layer: Foundations of a Recordable, Verifiable and Transferable Layer of Meaning", "license": "CC-BY-4.0", "code": null, "concept_doi": "10.5281/zenodo.22909342"}], "source_doi": "10.5281/zenodo.22909458", "source_url": "https://zenodo.org/records/22909458", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22909458"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}, {"id": "commitment-without-disclosure", "term_en": "commitment without disclosure", "term_de": "Festlegung ohne Offenlegung", "term_de_as_published": "Festlegung ohne Offenlegung", "alternate_names": [], "definition_en": "Publishing a cryptographic fingerprint of an entry while withholding its content, so that the date and form are fixed publicly and the entry can be opened and re-computed later by anyone, with no key, service or permission required.", "definition_de": "Man veröffentlicht den kryptografischen Fingerabdruck eines Eintrags und behält den Inhalt zurück. Damit sind Datum und genaue Form öffentlich festgelegt, während die Sache verschlossen bleibt. Der Eintrag kann später aufgedeckt und von jedem nachgerechnet werden — ohne Schlüssel, ohne Dienst, ohne Erlaubnis.", "definition_de_status": "author (verbatim from qa_dataset.jsonl line 21, sentences 1-3)", "plain_en": null, "plain_de": null, "family": "Entity Operating Layer — core terms", "codes": [], "web_url": null, "sources": [{"source": "S4", "doi": "10.5281/zenodo.22909458", "url": "https://zenodo.org/records/22909458", "title": "The Entity Operating Layer: Foundations of a Recordable, Verifiable and Transferable Layer of Meaning", "license": "CC-BY-4.0", "code": null, "concept_doi": "10.5281/zenodo.22909342"}], "source_doi": "10.5281/zenodo.22909458", "source_url": "https://zenodo.org/records/22909458", "license": "CC-BY-4.0", "license_url": "https://creativecommons.org/licenses/by/4.0/", "all_source_dois": ["10.5281/zenodo.22909458"], "license_note": "CC BY 4.0: reuse and adaptation allowed with attribution.", "creator": "Andreas Ehstand", "creator_orcid": "0009-0006-3773-7796", "programme": "AUGMANITAI", "attribution": "Andreas Ehstand, AUGMANITAI, ORCID 0009-0006-3773-7796"}];
